	["Acento: %s"] = "强调色：%s",
	["Acepta y entrega cualquier misión que se cruce en tu camino, sea o no de tu ruta."] = "接受并交付路上遇到的任何任务，无论是否在你的路线上。",
	["Acepta y entrega solo las misiones que te sirven para la ruta que sigues. Tu registro queda limpio."] = "只接受和交付对你当前路线有用的任务。任务日志保持整洁。",
	["Aceptar"] = "确定",
	["Aceptar solas las misiones de la guía"] = "自动接受指南中的任务",
	["Aceptar y entregar solo las misiones de mi ruta"] = "只接受和交付我路线上的任务",
	["Aceptar y entregar todas las misiones"] = "接受并交付所有任务",
	["Acercar"] = "放大",
	["Acomoda tus marcos"] = "摆放你的框体",
	["Activa máquinas en las paredes que sueltan bombas que caminan: pulsa el botón junto a la máquina para apagarla, o maten las bombas antes de que lleguen."] = "他会启动墙上的机器，放出会走路的炸弹：按机器旁的按钮可以关掉它，或者在炸弹走过来之前打掉。",
	["Activar el modo limpio"] = "开启简洁模式",
	["Activo"] = "已生效",
	["Actual"] = "当前",
	["Actualizar mi guía"] = "更新我的指南",
	["Actualizar mis barras"] = "更新我的动作条",
	["Actualízala con la app de CurseForge o con el zip más reciente y luego usa /reload."] = "请用 CurseForge 应用或最新的 zip 更新，然后输入 /reload。",
	["Actualízalo con la app de CurseForge o con el zip más reciente y luego reinicia el juego o usa /reload."] = "请使用 CurseForge 应用或最新的压缩包更新，然后重启游戏或输入 /reload。",
	["Aflicción"] = "痛苦",
	["Aflicción para subir"] = "痛苦（升级）",
	["Agarras a varios enemigos a la vez."] = "你能同时拉住多个敌人。",
	["Agilidad"] = "敏捷",
	["Agrega tramos arriba: Alfa elige las misiones por ti."] = "在上方添加路段：Alfa 会为你选择任务。",
	["Agrega una línea con el objetivo de esa unidad; si te tiene a ti, lo dice."] = "添加一行显示该单位的目标；如果目标是你，会特别标出。",
	["Agregada"] = "已加入",
	["Agregada a tu plan de misiones"] = "已加入你的任务计划",
	["Agregado a tu ruta"] = "已加入你的路线",
	["Agregar a mi plan"] = "加入我的计划",
	["Agregar a mi plan de misiones"] = "加入我的任务计划",
	["Agregar a mi ruta"] = "加入我的路线",
	["Agregar un tramo:"] = "添加路段：",
	["Agrégale uno en la página Ruta."] = "在“路线”页面添加一个。",
	["Agua y comida"] = "水和食物",
	["Aguante"] = "耐力",
	["Ahora"] = "现在",
	["Ahora ganas la XP normal"] = "现在获得的是正常经验值",
	["Ahora no"] = "暂不",
	["Ahora no sale: Alfa busca cómo unirse a la manada."] = "目前未发送：Alfa 正在寻找连接狼群的方式。",
	["Ahora no se puede"] = "现在无法进行",
	["Ahora no se puede anunciar"] = "现在无法通报",
	["Ahora no se pueden enviar mensajes (en una instancia o con una cuenta de prueba). %s"] = "现在无法发送消息（在副本中或使用试玩账号）。%s",
	["Ahora usan: %s. Activa los pesos de %s para que Alfa compare el equipo como lo pide tu build."] = "目前使用：%s。启用%s的权重，让 Alfa 按你的方案要求比较装备。",
	["Ahora va por el canal oculto de Alfa."] = "现在通过 Alfa 的隐藏频道发送。",
	["Ahora va por tu hermandad: el canal oculto de Alfa no está disponible, así que solo te ven quienes comparten en tu hermandad."] = "现在通过你的公会发送：Alfa 的隐藏频道不可用，所以只有公会中共享位置的人能看到你。",
	["Ahora: %d %% del nivel %d"] = "现在：%d %%（%d 级）",
	["Ahora: %s."] = "现在：%s。",
	["Ahí no hay ninguna zona: pon el marcador sobre tierra."] = "那里没有任何区域：请把标记放在陆地上。",
	["Ahí no se puede poner la flecha."] = "无法在那里设置箭头。",
	["Ahí nos organizamos para todo. Haz clic en el enlace y cópialo con Ctrl+C."] = "我们在那里安排一切活动。点击链接后用 Ctrl+C 复制。",
	["Ajustar"] = "调整",
	["Ajustar los avisos"] = "调整提醒",
	["Ajustes"] = "设置",
	["Ajustes de Bolsas"] = "背包设置",
	["Ajustes de mazmorras"] = "地下城设置",
	["Ajustes del medidor"] = "伤害统计设置",
	["Al armar tus rutas, Alfa deja fuera las que piden élites."] = "创建路线时，Alfa 会排除需要对付精英的任务。",
	["Al comerciante"] = "卖给商人",
	["Al comparar objetos, Alfa valora más lo que pide %s: lo de arriba en la lista de estadísticas."] = "比较物品时，Alfa 更看重%s需要的属性：即属性列表上方的那些。",
	["Al día"] = "已分配完",
	["Al elegir un build, las flechas de mejora de tus bolsas valoran lo que ese build necesita."] = "选择方案后，背包中的提升箭头会按该方案的需要评估。",
	["Al empezar aturde a quien lo despertó en el altar: es normal."] = "开场时他会击晕在祭坛唤醒他的人：这是正常的。",
	["Al enemigo le queda poca vida: remátalo."] = "敌人生命值很低：补上最后一击。",
	["Al final de la pelea se enfurece y pega más rápido: guarda curación para ese momento."] = "战斗末尾他会激怒，攻击变快：留好治疗应对那个阶段。",
	["Al final se enfurece: guarden su mejor daño para el final."] = "她在最后会激怒：把最强的输出留到最后。",
	["Al final, habla con el Discípulo de Naralex y protégelo mientras camina: así aparece el último jefe."] = "最后，与纳拉雷克斯的信徒对话，并在他行走时保护他：这样最终首领才会出现。",
	["Al hablar con quien da una misión de tu ruta, se acepta sola. Mayús la deja para ti."] = "与提供你路线上任务的人交谈时，会自动接受。按住 Shift 则由你自己决定。",
	["Al hablar con un banquero se abre el banco de Alfa, con depositar rápido. La primera visita de cada personaje muestra el del juego: así recibe su primera pestaña."] = "与银行职员交谈时会打开 Alfa 银行，可快速存放。每个角色第一次访问时会显示游戏自带的银行：这样才能获得第一个标签页。",
	["Al llegar a una ciudad o posada. También repite la nota de entrenar de la guía cuando su ventana está oculta."] = "到达城镇或旅店时提醒。指南窗口隐藏时，也会重复指南里的训练提示。",
	["Al morir aparecen cuatro abisarios que caminan juntos por el patio: prepárense para pelear con varios."] = "他死后会出现四个虚空行者，一起穿过庭院：准备好同时对付多个敌人。",
	["Al morir llegan muchos aprendices: prepárense para muchos enemigos a la vez."] = "他死后会冲来大量学徒：准备好同时面对很多敌人。",
	["Al objetivo le queda poca vida: Ejecutar lo remata usando tu ira."] = "目标生命值很低：用斩杀消耗怒气终结它。",
	["Al objetivo le queda poca vida: el martillo lo remata a distancia."] = "目标生命值很低：愤怒之锤可在远处终结它。",
	["Al pasar el ratón por un objeto: «Tienes 12 (Toxic: 7 en bolsas, Alt: 5 en banco)», con todos tus personajes."] = "鼠标指向物品时显示：“你有 12 个（Toxic：背包中 7、Alt：银行中 5）”，统计你所有角色。",
	["Al pasar el ratón sobre un objeto: su precio en la subasta, lo que paga el comerciante y qué te conviene."] = "鼠标指向物品时显示：拍卖行价格、商人收购价，以及怎么处理最划算。",
	["Al recibir daño suelta pedazos más pequeños: mátenlos con ataques en área."] = "受到伤害时会分裂出更小的碎片：用范围攻击清掉。",
	["Al subir de nivel (y al entrar, si te quedan puntos), un aviso dice qué talento poner, con el botón para aplicarlo."] = "升级时（以及登录时若还有未分配点数），会提示该点哪个天赋，并附应用按钮。",
	["Al subir de nivel te muestra qué aprender y cuánto cuesta."] = "升级时显示可学的技能和费用。",
	["Al subir de nivel, un aviso dice qué aprender, cuánto cuesta y con qué entrenador, con el botón Llévame."] = "升级时，会提示该学什么、多少钱、找哪位训练师，并附“带我去”按钮。",
	["Alejar"] = "缩小",
	["Alejar más la cámara"] = "镜头拉得更远",
	["Alertas"] = "警示",
	["Alfa"] = "Alfa",
	["Alfa (el estilo propio, por omisión), Clásico WoW (marcos y letras del juego) o Cristal (transparente, con el acento que elijas). El modo compacto y tus colores funcionan en los tres."] = "Alfa（专属风格，默认）、经典 WoW（游戏的框体和字体）或玻璃（透明，搭配你选择的强调色）。紧凑模式和你的颜色在三种风格中都可用。",
	["Alfa 1.0 ya está aquí"] = "Alfa 1.0 来了",
	["Alfa abre sin sonido. Lo enciendes cuando quieras en Ajustes > Estilo y sonido."] = "Alfa 打开时默认无声。随时可在“设置 > 风格与声音”中开启。",
	["Alfa arma la ruta más corta para cobrarlas, junta por PNJ. La flecha usa vuelos y tu piedra de hogar cuando conviene, y te avisa si una entrega queda lejos."] = "Alfa 会规划交付它们的最短路线，按 NPC 分组。箭头会在划算时使用飞行和炉石，并在交付点很远时提醒你。",
	["Alfa borrará lo que guardó de %s: sus bolsas, su banco y su equipo. Si vuelves a jugar con él, se guarda de nuevo."] = "Alfa 将删除为%s保存的数据：背包、银行和装备。再次用该角色登录时会重新保存。",
	["Alfa elige las misiones que más XP dan cerca de ti, en tres tandas."] = "Alfa 会分三批选出你附近经验最多的任务。",
	["Alfa elige todo: misiones ordenadas por XP por distancia y tus misiones de clase."] = "全部由 Alfa 挑选：按经验与距离之比排序的任务，再加上你的职业任务。",
	["Alfa está armando tu ruta..."] = "Alfa 正在生成你的路线...",
	["Alfa está eligiendo..."] = "Alfa 正在挑选...",
	["Alfa está leyendo tu clase"] = "Alfa 正在读取你的职业",
	["Alfa está oculto: clic para mostrarlo y abrir su ventana"] = "Alfa 已隐藏：点击以显示并打开其窗口",
	["Alfa lee el medidor oficial del juego. Enciéndelo y aquí verás el daño de tu grupo; su ventana puedes ocultarla en el Modo de edición."] = "Alfa 读取游戏官方的伤害统计。开启后，这里会显示你队伍的伤害；它的窗口可以在编辑模式中隐藏。",
	["Alfa los cambia por el rango nuevo sin moverlos de lugar."] = "Alfa 会把它们换成新等级，位置不变。",
	["Alfa mide los caminos (vuelos y piedra de hogar): tarda unos segundos."] = "Alfa 正在计算路程（飞行和炉石）：需要几秒钟。",
	["Alfa no pudo armar el camino a %s. Míralo en la Enciclopedia."] = "Alfa 无法规划前往%s的路线。请在百科中查看。",
	["Alfa no tiene datos de esto todavía."] = "Alfa 还没有这方面的数据。",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones» de Comodidades."] = "Alfa 不会接受对你路线无用的任务，也不会自动交付它们。便利功能中的“所有任务”也会遵守这一点。",
	["Alfa ordena las paradas para que no camines de más. Tarda unos segundos y no traba el juego."] = "Alfa 会安排站点顺序，让你不多走冤枉路。需要几秒钟，不会卡住游戏。",
	["Alfa revisa su base de objetos sin trabar el juego. Tarda unos segundos la primera vez."] = "Alfa 会在不卡住游戏的情况下检查物品数据库。第一次需要几秒钟。",
	["Alfa revisa su base de objetos, se queda con lo que tu clase puede usar cerca de tu nivel y lo compara con lo que llevas, con los pesos de tu build."] = "Alfa 会检查物品数据库，留下你的职业在你等级附近能用的物品，并按你方案的权重与身上的装备比较。",
	["Alfa se está uniendo al canal oculto de La Jauría. En unos segundos ves a quien comparte."] = "Alfa 正在加入 La Jauría 的隐藏频道。几秒后就能看到正在共享的人。",
	["Alfa tampoco tiene todavía una prioridad para tu clase con lo que sabes. Los avisos de reacción y el medidor sí funcionan."] = "Alfa 也还没有针对你的职业和已学技能的优先级。反应提醒和伤害统计仍然可用。",
	["Alfa te avisa aquí de lo importante: equipo por reparar, bolsas llenas, habilidades nuevas, tu buff y tu descanso."] = "Alfa 会在这里提醒你重要的事：需要修理的装备、满了的背包、新技能、你的增益效果和休息状态。",
	["Alfa te avisa del equipo gastado, las bolsas llenas, lo que puedes entrenar, tu buff y tu descanso. Aquí eliges cuáles y cuándo."] = "Alfa 会提醒你装备磨损、背包已满、可训练的技能、你的增益效果和休息状态。在这里选择提醒哪些以及何时提醒。",
	["Alfa te lleva paso a paso, con la flecha y la ruta en el mapa. Elige la de tu zona y tu nivel."] = "Alfa 会用箭头和地图上的路线一步步带你。选择适合你所在区域和等级的指南。",
	["Alfa todavía no tiene builds para tu clase"] = "Alfa 还没有适合你职业的方案",
	["Alfa vuelve a elegir desde donde estás ahora (las misiones fijas se quedan)."] = "Alfa 会从你现在的位置重新挑选（已固定的任务保留）。",
	["Alfa · Top %d de %s (%s%s)"] = "Alfa · 前 %d 名 %s（%s%s）",
	["Alfa, Clásico WoW o Cristal, la flecha del lobo y el aullido."] = "Alfa、经典 WoW 或玻璃风格，狼形箭头和狼嚎。",
	["Alfa: agregar a mi plan de misiones"] = "Alfa：加入我的任务计划",
	["Alfa: capas del mapa"] = "Alfa：地图图层",
	["Alfa: cerrar mis misiones"] = "Alfa：完成我的任务",
	["Alfa: quitar de mi plan de misiones"] = "Alfa：从我的任务计划中移除",
	["Alfa_Codex está apagado en la lista de addons."] = "Alfa_Codex 在插件列表中被关闭了。",
	["Alianza"] = "联盟",
	["Alquimia"] = "炼金术",
	["Alt"] = "Alt",
	["Alt+clic en un objeto abre su ficha"] = "Alt+点击物品可打开其详情页",
	["Alto"] = "高度",
	["Amenaza"] = "威胁",
	["Ancho"] = "宽度",
	["Anillos"] = "戒指",
	["Animación anterior"] = "上一个动作",
	["Animación siguiente"] = "下一个动作",
	["Anterior"] = "上一场",
	["Antes de entrar"] = "进本之前",
	["Antes de salir de caza, unas preguntas rápidas: cómo quieres que se vea Alfa, qué misiones toma por ti y si quieres el aullido."] = "出发狩猎前，先回答几个快速问题：Alfa 的外观、由它替你接哪些任务，以及是否要狼嚎。",
	["Antes de salir de caza, unas preguntas rápidas: cómo quieres que se vea Alfa, qué misiones toma por ti, si compartes tu ubicación con La Jauría y si quieres el aullido."] = "出发狩猎前，先回答几个快速问题：Alfa 的外观、由它替你接哪些任务、是否与 La Jauría 共享你的位置，以及是否要狼嚎。",
	["Antes hay que hacer otra misión"] = "需要先完成另一个任务",
	["Antes necesitas"] = "前置条件",
	["Antes necesitas otra misión"] = "需要先完成另一个任务",
	["Antes: %s"] = "先完成：%s",
	["Antes: %s."] = "先完成：%s。",
	["Anunciar"] = "通报",
	["Anunciar en el chat"] = "在聊天中通报",
	["Anunciar en el grupo"] = "通报给队伍",
	["Apaga la música y el ambiente y sube los efectos para que oigas cuando pica, aunque el juego esté en segundo plano. Al terminar, todo vuelve a como estaba."] = "关闭音乐和环境音并调高音效，即使游戏在后台也能听到鱼上钩。钓完后一切都会恢复原样。",
	["Apagada"] = "已关闭",
	["Apagadas"] = "已关闭",
	["Apagado"] = "已关闭",
	["Apagado, solo las acepta y la entrega la haces tú."] = "关闭时只自动接受，交付由你自己来。",
	["Apagados"] = "已关闭",
	["Aparece al final del evento del Discípulo de Naralex: protege al druida mientras camina."] = "他在纳拉雷克斯的信徒事件结束时出现：在德鲁伊行走时保护他。",
	["Aparece al tocar el gong por tercera vez, después de dos oleadas de arañas."] = "第三次敲响铜锣时出现，前面会先来两波蜘蛛。",
	["Aparece con una misión de la Horda (un objeto en el agua). Lanza escarcha."] = "通过一个部落任务（水中的一件物品）召唤出来。会施放冰霜法术。",
	["Aparece en el evento de la explosivista: protégela mientras llegan oleadas de troggs."] = "他在爆破专家的事件中出现：在一波波穴居人冲来时保护她。",
	["Aparecen marcos de ejemplo: arrástralos a donde los quieras y ajusta su tamaño. Así se verá tu grupo."] = "会出现示例框体：把它们拖到你想要的位置并调整大小。你的队伍就会这样显示。",
	["Aplaudir"] = "鼓掌",
	["Aplicar"] = "应用",
	["Aplicar %d puntos"] = "应用 %d 点",
	["Aprende Pesca"] = "学习钓鱼",
	["Aprende Pesca con un instructor de pesca (hay en las capitales) y compra una caña. Luego vuelve aquí."] = "找钓鱼训练师学习钓鱼（各主城都有），再买一根鱼竿，然后回到这里。",
	["Aprender de tus búsquedas"] = "从你的搜索中学习",
	["Aprendiste un hechizo que le queda mejor a tus clics:"] = "你学会了一个更适合点击施法的法术：",
	["Apréndelos con el entrenador de tu clase, en cualquier capital."] = "向你的职业训练师学习，任何主城都有。",
	["Apágalo si no quieres que Alfa toque tu tecla ni tus ajustes al pescar."] = "如果不想让 Alfa 在钓鱼时改动你的按键和设置，请关闭此项。",
	["Aquí aparecerán los demás módulos de Alfa (bolsas, rutas, mundo y más) en cuanto estén instalados."] = "Alfa 的其他模块（背包、路线、世界等）安装后会显示在这里。",
	["Aquí el juego no da tu posición (por ejemplo, dentro de una mazmorra)."] = "游戏在这里不提供你的位置（例如在地下城内）。",
	["Aquí el juego no deja compartir nada. Al salir, tu rastro vuelve a salir solo."] = "游戏在这里不允许共享任何内容。离开后，你的踪迹会自动恢复发送。",
	["Aquí no hay nodos que recolectar"] = "这里没有可采集的采集点",
	["Aquí sale por qué se activó la habilidad."] = "这里会显示技能被触发的原因。",
	["Aquí ves todo lo que hay que saber, con qué hacer después."] = "这里显示你需要知道的一切，以及接下来该做什么。",
	["Arañazo: sangrado con el tiempo."] = "斜掠：持续流血。",
	["Arcano"] = "奥术",
	["Arcano para subir"] = "奥术（升级）",
	["Arco"] = "弓",
	["Arena"] = "沙色",
	["Arma"] = "武器",
	["Arma con tu ruta lo que necesitas para poder tomarla: el nivel o las misiones de antes."] = "用你的路线安排接取它所需的条件：等级或前置任务。",
	["Arma de asta"] = "长柄武器",
	["Arma de dos manos"] = "双手武器",
	["Arma de dos manos, sellos y juicios: el paladín que mejor sube en solitario."] = "双手武器、圣印和审判：单人升级最快的圣骑士。",
