	["Consejos"] = "提示",
	["Consejos de equipo apagados."] = "装备建议已关闭。",
	["Consejos para jugarlo"] = "玩法建议",
	["Conserva %s: vale más de otra forma."] = "保留%s：用其他方式更值钱。",
