	["Encantamiento"] = "附魔",
	["Encender el registro"] = "开启记录",
	["Encender la pesca"] = "开启钓鱼",
	["Encender las recomendadas"] = "开启推荐项",
	["Encenderla"] = "开启",
	["Encenderlos"] = "开启",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "开启：即使被筛选条件排除也会加入计划。关闭：不加入。",
	["Encendido"] = "已开启",
	["Encendido y tecla"] = "开关与按键",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "开启：钓鱼时双击会重新抛竿，按住 Shift、Ctrl 或 Alt 双击则收竿。关闭：反过来。",
	["Enciclopedia"] = "百科",
	["Enciende las comodidades recomendadas"] = "开启推荐的便利功能",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "对鼠标指向角色或生物时出现的鼠标提示启用下方的改进。",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "对试衣间（Ctrl + 点击物品）启用下方的改进。",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "启用下方的改进，每一项都可以单独关闭。部分插件在 /reload 后才会把按钮调整到方形小地图上。",
	["Enciende primero la guía en el minimapa."] = "请先开启小地图上的指南。",
	["Enciende primero los servicios."] = "请先开启服务。",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "开启后，战斗中会在一个可移动的小图标里显示现在该用哪个技能以及接下来用哪些。",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "在下方的“框体”中开启，即可查看队友的生命值并一键治疗。",
	["Enciéndelos en la página Curación."] = "在“治疗”页面中开启。",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "开启后可查看队伍的生命值，并一键治疗。",
	["Enemigo raro"] = "稀有敌人",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "先定住怪物，拉开距离后再施放读条长的法术。",
	["Entendido"] = "知道了",
	["Entereza"] = "真言术：韧",
	["Entra al juego con él una vez."] = "用它登录游戏一次。",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "带着整洁的任务日志进去：先交付你已有的任务。",
	["Entrada"] = "入口",
	["Entrada enemiga"] = "敌方入口",
	["Entradas de mazmorras"] = "地下城入口",
	["Entradas en el minimapa"] = "小地图上的入口",
	["Entraste a %s"] = "你进入了%s",
