	["Hay enemigos que se convierten en lobos y otros que asustan: no corran si los asustan, esperen."] = "有些敌人会变成狼，有些会施放恐惧：被恐惧时别慌，等效果过去。",
	["Hay mucha agua: si nadas bajo el agua, mira tu barra de respiración y sube a tomar aire."] = "这里水很多：潜水时留意呼吸条，记得上浮换气。",
	["Hay muchos no-muertos y jabaespines: lleven algo para quitar enfermedades si su grupo puede."] = "亡灵和野猪人很多：如果队伍里有人能驱散疾病就准备好。",
	["Hay muchos troggs y elementales de fuego juntos: tiren de uno o dos grupos a la vez, no más."] = "穴居人和火元素挤在一起：一次只拉一两群，别多拉。",
	["Hay una guía de Alfa"] = "有 Alfa 指南",
