	["Haz doble clic derecho en el mundo para lanzar la caña, sin usar la tecla. Nunca en combate ni en vuelo."] = "在游戏世界中右键双击即可抛竿，不用按键。战斗中和飞行中不会触发。",
	["Haz doble clic derecho en el mundo para lanzar. Cuando pique, haz clic derecho sobre el corcho para recoger."] = "在游戏世界中右键双击抛竿。鱼上钩时，右键点击鱼漂收竿。",
