	["No se conoce su botín"] = "战利品未知",
	["No se encontró el chat."] = "找不到聊天框。",
	["No se encontró la carpeta Alfa_Codex. Reinstala Alfa completo."] = "找不到 Alfa_Codex 文件夹。请重新完整安装 Alfa。",
	["No se encontró nada mejor cerca de tu nivel. Vuelve a buscar al subir unos niveles."] = "在你等级附近没找到更好的装备。升几级后再搜索吧。",
	["No se pudieron leer los datos del juego."] = "无法读取游戏数据。",
	["No se pudo"] = "无法完成",
	["No se pudo abrir el Codex de Alfa (la base de objetos). Revisa que el addon Alfa Codex esté activado."] = "无法打开 Alfa 的 Codex（物品数据库）。请检查 Alfa Codex 插件是否已启用。",
	["No se pudo armar la guía (%s)."] = "无法生成指南（%s）。",
