	["No siempre aparece en la mina: si lo ves, es un jefe más con buen botín."] = "他不一定会在矿洞里出现：如果碰到了，就是一个掉落不错的额外首领。",
	["No siempre aparece. Pone un dolor de sombras: cura a quien lo tenga."] = "不一定会出现。会施放暗影痛：治疗中招的人。",
