	["Objetos obtenidos"] = "已获得的物品",
	["Oculta el botón con el número de addons en la esquina del minimapa. Esos addons se siguen abriendo con su comando, como /alfa."] = "隐藏小地图角落显示插件数量的按钮。这些插件仍可用各自的命令打开，比如 /alfa。",
	["Oculta el rastreador del juego a la derecha de la pantalla, con sus misiones, logros y profesiones. No con la interfaz de mando."] = "隐藏屏幕右侧游戏自带的追踪器，包括其中的任务、成就和专业。手柄界面下无效。",
	["Oculta lo que tu clase no puede usar o no le conviene: armadura de otro tipo, armas que no usas, piezas sin nada para tu especialización."] = "隐藏你的职业不能用或不适合的物品：其他护甲类型、你不用的武器、没有适合你专精属性的装备。",
	["Oculta los avisos que son para otro papel (por ejemplo, los del tanque si tú curas)."] = "隐藏针对其他职责的警报（例如你是治疗时隐藏坦克的警报）。",
