	["Todo en orden"] = "一切正常",
	["Todo junto"] = "全部合并",
	["Todo junto muestra cada casilla en su lugar; por categorías agrupa equipo, consumibles, misiones y materiales; por bolsa pone cada bolsa en su bloque."] = "“全部合并”让每一格都在原位；“按类别”把装备、消耗品、任务物品和材料分组；“按背包”让每个背包单独成块。",
	["Todo listo"] = "一切就绪",
	["Todo lo que no sea equipo"] = "所有非装备物品",
	["Todo lo que se pinta en tus mapas, en un solo lugar. Lo de otros módulos de Alfa también llega aquí."] = "你地图上显示的所有内容，集中在一处。Alfa 其他模块的内容也会出现在这里。",
	["Todo nivel"] = "所有等级",
	["Todo objeto, PNJ, misión, zona y raro, con dónde conseguirlo y «Guíame»."] = "所有物品、NPC、任务、区域和稀有怪，附获取地点和“指引我”。",
	["Todo oficio"] = "所有职能",
	["Todo para el daño: críticos, sangrados y Abrumar muy seguido. Matas rapidísimo, pero no hay defensa extra: si se te juntan muchos, corre."] = "一切为了伤害：暴击、流血和频繁的压制。杀怪极快，但没有额外防御：如果被一群怪围住，就快跑。",
	["Todo subtipo"] = "所有子类型",
	["Todo tipo"] = "所有类型",
	["Todos"] = "全部",
	["Todos llegan a %s"] = "都通往%s",
	["Todos los de ese tipo, o solo uno (por ejemplo, solo cobre). Entre paréntesis, cuántos hay en tu zona."] = "该类型的全部，或只选一种（例如只采铜）。括号里是你所在区域的数量。",
	["Todos los materiales"] = "所有材料",
	["Todos los niveles"] = "所有等级",
	["Todos los objetos, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "所有物品、NPC、任务、区域和稀有，即使你没有：谁掉落及掉落几率、谁出售及在哪里、哪个任务给予以及如何前往。",
	["Todos los pasos"] = "所有步骤",
	["Todos los pasos de esta guía; clic en uno para verlo."] = "此指南的所有步骤；点击某一步即可查看。",
	["Todos los pasos de la guía en la ventana de guía."] = "在指南窗口中查看指南的所有步骤。",
	["Todos los tipos"] = "所有类型",
	["Todos tus puntos ya están gastados y parte de ellos fuera de este build. Para cambiarte a este build, reinicia tus talentos con tu entrenador de clase; después Alfa te los aplica con un clic."] = "你的点数已全部分配，其中一部分不在这个方案里。想换成这个方案，请先找职业训练师重置天赋；之后 Alfa 一键就能帮你点好。",
	["Todos: también los avisos leves. Solo los graves: únicamente lo que puede matarte."] = "全部：也包括轻微的警报。仅严重：只显示可能致命的。",
	["Toma el botín de la pesca enseguida, aunque tengas apagado el botín automático del juego."] = "立即拾取钓鱼所得，即使你关闭了游戏的自动拾取。",
