	["Tu hermandad conectada"] = "在线公会成员",
	["Tu historial"] = "你的历史记录",
	["Tu instalación está mezclada o incompleta (%s). Cierra el juego, borra todas las carpetas de Alfa en Interface/AddOns e instala Alfa de nuevo con la app de CurseForge o el zip más reciente (no \"Source code\")."] = "你的安装混杂了不同版本或不完整（%s）。请关闭游戏，删除 Interface/AddOns 中所有 Alfa 文件夹，然后用 CurseForge 应用或最新的压缩包重新安装 Alfa（不要用“Source code”）。",
	["Tu libro no tiene hechizos para aliados"] = "你的法术书中没有可对友方使用的法术",
	["Tu lista de sonidos"] = "你的声音名单",
	["Tu lista de sonidos está vacía. Agrega uno con /alfa silenciar <número>."] = "你的声音名单是空的。用 /alfa silenciar <编号> 添加一个。",
	["Tu lista de sonidos quedó vacía."] = "你的声音名单已清空。",
	["Tu lista: síguelos con la flecha, compártelos con el grupo, cámbialos o bórralos."] = "你的列表：用箭头跟随、分享给队伍、更改或删除。",
	["Tu manada"] = "你的狼群",
	["Tu manada en el mapa: tu grupo y quienes usan Alfa y comparten. Síguelos con la flecha, invítalos y conoce al clan."] = "地图上的狼群：你的队伍以及使用 Alfa 并共享位置的人。用箭头跟随他们、邀请他们，并认识公会。",
	["Tu manada está fuera del mapa"] = "你的狼群不在地图上",
	["Tu manada te ve en el mapa y te puede seguir con la flecha. Lo apagas cuando quieras en la página de La Jauría."] = "狼群能在地图上看到你，并可用箭头跟随你。随时可在 La Jauría 页面中关闭。",
	["Tu mapa"] = "你的地图",
	["Tu mapa del ratón está vacío: elige algo en una ranura primero."] = "你的鼠标绑定是空的：请先为某个栏位选择动作。",
	["Tu mascota"] = "你的宠物",
	["Tu mascota hace gran parte del trabajo y aguanta los golpes: la forma más fácil y segura de subir con cazador."] = "宠物包办大部分工作，还替你挨打：猎人最简单、最安全的升级方式。",
	["Tu munición"] = "你的弹药",
	["Tu nivel"] = "你的等级",
	["Tu objetivo esquivó: Abrumar no se puede esquivar y pega fuerte. Necesita actitud de batalla."] = "你的目标躲闪了：压制无法被躲闪，而且伤害很高。需要战斗姿态。",
	["Tu personaje deja de decir \"No tengo suficiente maná\", \"Eso todavía no está listo\" y parecidas. El texto rojo sigue."] = "你的角色不再说“法力值不足”“还没准备好”之类的话。红色文字仍会显示。",
	["Tu pieza más gastada: %s al %d %%."] = "你磨损最严重的装备：%s，耐久 %d %%。",
