	["Tu siguiente talento"] = "你的下一个天赋",
	["Tu tecla del mapa (%s) lo abre."] = "你的地图键（%s）可打开它。",
	["Tu tecla y tus ajustes del juego quedan como siempre. Enciéndela para pescar con una sola tecla."] = "你的按键和游戏设置保持不变。开启后即可用一个键钓鱼。",
